<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\{Document,Brand,Product,Industry};use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;use Illuminate\Support\Str;
class DocumentController extends Controller {public function index(Request $r){$q=Document::with(['brand','product']);if($r->type)$q->where('document_type',$r->type);return view('admin.documents.index',['documents'=>$q->latest()->paginate(25)]);}public function create(){return view('admin.documents.form',$this->data()+['document'=>new Document]);}public function store(Request $r){Document::create($this->validated($r));return redirect()->route('admin.documents.index')->with('success','Document created.');}public function edit(Document $document){return view('admin.documents.form',$this->data()+compact('document'));}public function update(Request $r,Document $document){$document->update($this->validated($r,$document));return back()->with('success','Document updated.');}public function destroy(Document $document){if($document->file_path)Storage::disk('public')->delete($document->file_path);$document->delete();return back()->with('success','Document deleted.');}private function data(){return ['brands'=>Brand::orderBy('name')->get(),'products'=>Product::orderBy('name')->get(),'industries'=>Industry::orderBy('name')->get()];}private function validated(Request $r,?Document $d=null){$v=$r->validate(['title'=>'required|max:255','slug'=>'nullable|max:255|unique:documents,slug,'.($d?->id??'NULL'),'document_type'=>'required|in:catalogue,datasheet,manual,certificate,cad,drawing,selection_guide,case_study,video,other','brand_id'=>'nullable|exists:brands,id','product_id'=>'nullable|exists:products,id','industry_id'=>'nullable|exists:industries,id','language'=>'required|max:10','external_url'=>'nullable|url','file'=>'nullable|file|max:51200','status'=>'nullable|boolean']);$v['slug']=$v['slug']?:Str::slug($v['title']);$v['status']=$r->boolean('status');if($r->hasFile('file')){$f=$r->file('file');$v['file_path']=$f->store('documents','public');$v['file_type']=$f->getClientOriginalExtension();$v['file_size']=$f->getSize();if($d?->file_path)Storage::disk('public')->delete($d->file_path);}unset($v['file']);return $v;}}
